const body = $('Webhook \u2014 Miss\u00e3o Semanal').first().json.body ||
             $('Webhook \u2014 Miss\u00e3o Semanal').first().json;
const { nicho, cidades, meta_semanal = 150 } = body;
if (!nicho?.trim()) throw new Error('Payload inv\u00e1lido: "nicho" \u00e9 obrigat\u00f3rio.');
if (!cidades)       throw new Error('Payload inv\u00e1lido: "cidades" \u00e9 obrigat\u00f3rio.');
const cidadesArr = Array.isArray(cidades) ? cidades : [cidades];
if (cidadesArr.length === 0) throw new Error('Pelo menos uma cidade \u00e9 obrigat\u00f3ria.');
const lote_diario = Math.ceil(meta_semanal / 7);
const apify_limit = Math.ceil(lote_diario * 1.5);
const cidade_principal = cidadesArr[0];
const search_query = nicho + ' ' + cidade_principal;
return [{ json: { nicho, cidades: cidadesArr, cidade_principal, lote_diario, apify_limit, search_query } }];

const run = $input.item.json.data || $input.item.json;
if (!run.defaultDatasetId) {
  throw new Error('Apify run sem dataset. Status: ' + (run.status || 'desconhecido'));
}
if (run.status !== 'SUCCEEDED') {
  throw new Error('Apify run falhou. Status: ' + run.status);
}
return { json: { datasetId: run.defaultDatasetId, runId: run.id, itemCount: run.stats?.itemCount || 0 } };

const apifyItems = $input.all();
const missao = $('Code \u2014 Prepara Miss\u00e3o').first().json || {};
const blacklist = [];
const CONCORRENTE_KW = [
  'design','designer','criativo','criativa','arte','artista',
  'portfolio','portf\u00f3lio','branding','logo','logotipo',
  'ag\u00eancia','agencia','marketing','identidade visual','marca',
  'social media','tr\u00e1fego','gestor','gestora'
];
const seenUsernames = new Set();
const qualificados = [];
const descartados = { blacklist: 0, duplicado: 0, concorrente: 0, sem_username: 0 };
for (const item of apifyItems) {
  const entries = Array.isArray(item.json) ? item.json : [item.json];
  for (const p of entries) {
    if (!p) continue;
    // Suporta formato de perfil (username) e de post (ownerUsername)
    const rawUsername = p.username || p.ownerUsername || '';
    if (!rawUsername) { descartados.sem_username++; continue; }
    const username = rawUsername.toLowerCase().trim();
    if (seenUsernames.has(username)) { descartados.duplicado++; continue; }
    if (blacklist.includes(username)) { descartados.blacklist++; continue; }
    // Filtra concorrentes pelo caption/bio disponivel
    const textoBio = (p.biography || p.caption || '').toLowerCase();
    if (CONCORRENTE_KW.some(kw => textoBio.includes(kw))) { descartados.concorrente++; continue; }
    seenUsernames.add(username);
    const fullName = p.fullName || p.ownerFullName || rawUsername;
    const followers = Number(p.followersCount) || 0;
    const isBusinessAccount = p.isBusinessAccount === true;
    const extUrl = p.externalUrl || '';
    const picUrl = p.profilePicUrlHD || p.profilePicUrl || p.displayUrl || '';
    const cidade = (missao.cidades || [])[0] || '';
    // Score base: apareceu na busca do nicho = relevante
    let score = 40;
    if (followers >= 500 && followers <= 50000) score += 10;
    if (isBusinessAccount) score += 10;
    if (extUrl) score += 5;
    qualificados.push({ json: {
      Username: rawUsername,
      Nome_Empresa: fullName,
      Bio: (p.biography || p.caption || '').substring(0, 500),
      Link_IG: 'https://www.instagram.com/' + rawUsername + '/',
      External_URL: extUrl,
      Lead_Score: score,
      Followers: followers,
      Status: 'Curadoria',
      Foto_Perfil_URL: picUrl,
      Data_Entrada: new Date().toISOString(),
      Nicho: missao.nicho || '',
      Cidade: cidade,
      is_business: isBusinessAccount
    }});
  }
}
console.log('[SDR] Qualificados: ' + qualificados.length + ' | Descartados: ' + JSON.stringify(descartados));
if (qualificados.length === 0) return [{ json: { _sem_leads: true, total: 0, descartados } }];
return qualificados;

